interface IHexButton {
    icon: ReactNode;
    label: string;
    active: boolean;
    onClick: () => void;
}

export function HexButton({ icon, label, active, onClick }: IHexButton) {
    return (
        <button
            type="button"
            onClick={onClick}
            className="group relative flex h-full w-full cursor-pointer items-center justify-center overflow-visible border-none bg-transparent transition-all duration-500 hover:brightness-75 active:brightness-50"
        >
            <span
                className={cn(
                    'pointer-events-none absolute left-1/2 top-1/2 flex -translate-x-1/2 -translate-y-1/2 transition-opacity duration-500 group-hover:opacity-0',
                    active ? 'opacity-0' : 'opacity-100',
                )}
            >
                <HexDefault />
            </span>
            <span
                className={cn(
                    'pointer-events-none absolute left-1/2 top-1/2 flex -translate-x-1/2 -translate-y-1/2 transition-opacity duration-500 group-hover:opacity-100',
                    active ? 'opacity-100' : 'opacity-0',
                )}
            >
                <HexSelected />
            </span>
            <span
                className={cn(
                    'relative z-10 flex transition-all duration-500 group-hover:text-white group-active:scale-90',
                    active ? 'text-white' : 'text-[#dddddd]',
                )}
            >
                {icon}
            </span>
            <span
                className="pointer-events-none absolute left-1/2 top-0 z-[15] flex h-[1.5rem] w-max -translate-x-1/2 translate-y-full scale-75 items-center whitespace-nowrap rounded-[0.25rem] border border-white/10 px-[0.8125rem] text-[0.75rem] font-extrabold uppercase text-white opacity-0 transition-all duration-500 group-hover:-translate-y-full group-hover:scale-100 group-hover:opacity-100 group-hover:brightness-125"
                style={{
                    background:
                        'radial-gradient(50% 50% at 50% 50%, rgba(255, 255, 255, 0) 0%, rgba(255, 255, 255, 0.11) 100%), linear-gradient(0deg, rgba(221, 221, 221, 0.18), rgba(221, 221, 221, 0.18))',
                    backgroundBlendMode: 'screen',
                }}
            >
                {label}
            </span>
        </button>
    );
}
